/// \ingroup enumerations
/// \enum AMobjType
/// \installed_headerfile
/// \brief The type of an object.
enum AMobjType {
  /// The default tag, not a type signifier.
  AM_OBJ_TYPE_DEFAULT(0),

  /// A list.
  AM_OBJ_TYPE_LIST(1),

  /// A key-value map.
  AM_OBJ_TYPE_MAP(2),

  /// A list of Unicode graphemes.
  AM_OBJ_TYPE_TEXT(3);

  final int value;
  const AMobjType(this.value);

  static AMobjType fromValue(int value) => switch (value) {
    0 => AM_OBJ_TYPE_DEFAULT,
    1 => AM_OBJ_TYPE_LIST,
    2 => AM_OBJ_TYPE_MAP,
    3 => AM_OBJ_TYPE_TEXT,
    _ => throw ArgumentError('Unknown value for AMobjType: $value'),
  };
}

