/// \ingroup enumerations
/// \enum AMvalType
/// \installed_headerfile
/// \brief The type of an item's value.
enum AMvalType {
  /// An actor identifier value.
  AM_VAL_TYPE_ACTOR_ID(2),

  /// A boolean value.
  AM_VAL_TYPE_BOOL(4),

  /// A view onto an array of bytes value.
  AM_VAL_TYPE_BYTES(8),

  /// A change value.
  AM_VAL_TYPE_CHANGE(16),

  /// A change hash value.
  AM_VAL_TYPE_CHANGE_HASH(32),

  /// A CRDT counter value.
  AM_VAL_TYPE_COUNTER(64),

  /// A cursor value.
  AM_VAL_TYPE_CURSOR(128),

  /// The default tag, not a type signifier.
  AM_VAL_TYPE_DEFAULT(0),

  /// A document value.
  AM_VAL_TYPE_DOC(256),

  /// A 64-bit float value.
  AM_VAL_TYPE_F64(512),

  /// A 64-bit signed integer value.
  AM_VAL_TYPE_INT(1024),

  /// A mark.
  AM_VAL_TYPE_MARK(2048),

  /// A null value.
  AM_VAL_TYPE_NULL(4096),

  /// An object type value.
  AM_VAL_TYPE_OBJ_TYPE(8192),

  /// A UTF-8 string view value.
  AM_VAL_TYPE_STR(16384),

  /// A synchronization have value.
  AM_VAL_TYPE_SYNC_HAVE(32768),

  /// A synchronization message value.
  AM_VAL_TYPE_SYNC_MESSAGE(65536),

  /// A synchronization state value.
  AM_VAL_TYPE_SYNC_STATE(131072),

  /// A *nix timestamp (milliseconds) value.
  AM_VAL_TYPE_TIMESTAMP(262144),

  /// A 64-bit unsigned integer value.
  AM_VAL_TYPE_UINT(524288),

  /// An unknown type of value.
  AM_VAL_TYPE_UNKNOWN(1048576),

  /// A void.
  AM_VAL_TYPE_VOID(1);

  final int value;
  const AMvalType(this.value);

  static AMvalType fromValue(int value) => switch (value) {
    2 => AM_VAL_TYPE_ACTOR_ID,
    4 => AM_VAL_TYPE_BOOL,
    8 => AM_VAL_TYPE_BYTES,
    16 => AM_VAL_TYPE_CHANGE,
    32 => AM_VAL_TYPE_CHANGE_HASH,
    64 => AM_VAL_TYPE_COUNTER,
    128 => AM_VAL_TYPE_CURSOR,
    0 => AM_VAL_TYPE_DEFAULT,
    256 => AM_VAL_TYPE_DOC,
    512 => AM_VAL_TYPE_F64,
    1024 => AM_VAL_TYPE_INT,
    2048 => AM_VAL_TYPE_MARK,
    4096 => AM_VAL_TYPE_NULL,
    8192 => AM_VAL_TYPE_OBJ_TYPE,
    16384 => AM_VAL_TYPE_STR,
    32768 => AM_VAL_TYPE_SYNC_HAVE,
    65536 => AM_VAL_TYPE_SYNC_MESSAGE,
    131072 => AM_VAL_TYPE_SYNC_STATE,
    262144 => AM_VAL_TYPE_TIMESTAMP,
    524288 => AM_VAL_TYPE_UINT,
    1048576 => AM_VAL_TYPE_UNKNOWN,
    1 => AM_VAL_TYPE_VOID,
    _ => throw ArgumentError('Unknown value for AMvalType: $value'),
  };
}
